import{_ as a}from"./chunks/prontera-guild.BuH2I_WE.js";import{_ as d,o as e,c as l,ag as r}from"./chunks/framework.DGzMGr_a.js";const g=JSON.parse('{"title":"公会系统完全指南","description":"RO3公会创建、管理、成长全攻略，含公会技能、GVG组织、领地战策略。","frontmatter":{"title":"公会系统完全指南","description":"RO3公会创建、管理、成长全攻略，含公会技能、GVG组织、领地战策略。","lastUpdated":true},"headers":[],"relativePath":"guide/guild.md","filePath":"guide/guild.md","lastUpdated":1780229775000}'),n={name:"guide/guild.md"};function i(s,t,o,h,p,c){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="公会系统完全指南" tabindex="-1">公会系统完全指南 <a class="header-anchor" href="#公会系统完全指南" aria-label="Permalink to &quot;公会系统完全指南&quot;">​</a></h1><p>公会是RO3的核心社交组织，加入一个活跃公会将极大提升你的游戏体验。</p><h2 id="公会基础" tabindex="-1">公会基础 <a class="header-anchor" href="#公会基础" aria-label="Permalink to &quot;公会基础&quot;">​</a></h2><h3 id="创建公会" tabindex="-1">创建公会 <a class="header-anchor" href="#创建公会" aria-label="Permalink to &quot;创建公会&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>要求</th></tr></thead><tbody><tr><td>等级要求</td><td>Lv.30+</td></tr><tr><td>费用</td><td>50,000 Zeny</td></tr><tr><td>初始人数</td><td>至少3人</td></tr><tr><td>冷却时间</td><td>创建后7天内不可解散</td></tr></tbody></table><p><strong>创建步骤</strong>：</p><ol><li>前往主城（普隆德拉）找到公会管理员</li><li>提交创建申请并缴纳费用</li><li>邀请至少2名成员加入</li><li>设置公会名称和徽章</li></ol><h3 id="加入公会" tabindex="-1">加入公会 <a class="header-anchor" href="#加入公会" aria-label="Permalink to &quot;加入公会&quot;">​</a></h3><ul><li>通过公会列表搜索申请</li><li>接受公会成员的邀请</li><li>通过世界频道招募信息加入</li></ul><h2 id="公会管理" tabindex="-1">公会管理 <a class="header-anchor" href="#公会管理" aria-label="Permalink to &quot;公会管理&quot;">​</a></h2><h3 id="职位体系" tabindex="-1">职位体系 <a class="header-anchor" href="#职位体系" aria-label="Permalink to &quot;职位体系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职位</th><th>权限</th></tr></thead><tbody><tr><td>会长</td><td>全部权限</td></tr><tr><td>副会长</td><td>审批入会、发起GVG、管理仓库</td></tr><tr><td>精英</td><td>邀请成员、使用公会技能</td></tr><tr><td>成员</td><td>基本权限</td></tr><tr><td>见习</td><td>无特殊权限</td></tr></tbody></table><h3 id="公会贡献" tabindex="-1">公会贡献 <a class="header-anchor" href="#公会贡献" aria-label="Permalink to &quot;公会贡献&quot;">​</a></h3><p>贡献是公会系统的核心货币，可通过以下方式获得：</p><table tabindex="0"><thead><tr><th>方式</th><th>贡献值</th><th>说明</th></tr></thead><tbody><tr><td>每日签到</td><td>10点/天</td><td>最稳定的来源</td></tr><tr><td>公会任务</td><td>20-50点/次</td><td>每日可做3次</td></tr><tr><td>GVG参与</td><td>100点/次</td><td>获胜翻倍</td></tr><tr><td>捐献Zeny</td><td>1点/1,000 Zeny</td><td>每日上限10,000 Zeny</td></tr><tr><td>捐献材料</td><td>视材料价值而定</td><td>常见材料即可</td></tr></tbody></table><h3 id="公会商店" tabindex="-1">公会商店 <a class="header-anchor" href="#公会商店" aria-label="Permalink to &quot;公会商店&quot;">​</a></h3><p>贡献值可在公会商店兑换：</p><ul><li>经验药水（+30%经验，持续1小时）</li><li>精炼保护卷轴</li><li>公会限定头饰/外观</li><li>稀有材料</li></ul><h3 id="公会技能" tabindex="-1">公会技能 <a class="header-anchor" href="#公会技能" aria-label="Permalink to &quot;公会技能&quot;">​</a></h3><p>公会会长可消耗公会资金学习/升级技能：</p><table tabindex="0"><thead><tr><th>技能名</th><th>效果</th><th>最大等级</th></tr></thead><tbody><tr><td>经验加成</td><td>全成员经验获取+</td><td>10级（+20%）</td></tr><tr><td>负重增加</td><td>全成员负重量+</td><td>5级（+500）</td></tr><tr><td>HP增加</td><td>全成员最大HP+</td><td>10级（+15%）</td></tr><tr><td>SP增加</td><td>全成员最大SP+</td><td>10级（+15%）</td></tr><tr><td>GVG攻击</td><td>GVG中攻击力+</td><td>5级（+10%）</td></tr><tr><td>GVG防御</td><td>GVG中防御力+</td><td>5级（+10%）</td></tr></tbody></table><h2 id="gvg公会战" tabindex="-1">GVG公会战 <a class="header-anchor" href="#gvg公会战" aria-label="Permalink to &quot;GVG公会战&quot;">​</a></h2><p><img src="'+a+`" alt="RO3 骑士公会场景"></p><p>详见 <a href="/guide/gvg-strategy.html">GVG攻城战攻略</a></p><h3 id="公会战时间" tabindex="-1">公会战时间 <a class="header-anchor" href="#公会战时间" aria-label="Permalink to &quot;公会战时间&quot;">​</a></h3><ul><li><strong>常规GVG</strong>：每周三、六 20:00-21:00</li><li><strong>领土战</strong>：每周日 20:00-21:30</li><li><strong>赛季决赛</strong>：赛季末周六</li></ul><h3 id="公会战组织" tabindex="-1">公会战组织 <a class="header-anchor" href="#公会战组织" aria-label="Permalink to &quot;公会战组织&quot;">​</a></h3><p><strong>战前准备</strong>：</p><ol><li>提前30分钟公会频道集合</li><li>分配职业编队（坦克队/输出队/治疗队/骚扰队）</li><li>检查装备和药水储备</li><li>确认语音频道（推荐Discord/游戏内语音）</li></ol><h2 id="公会收入来源" tabindex="-1">公会收入来源 <a class="header-anchor" href="#公会收入来源" aria-label="Permalink to &quot;公会收入来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>收入</th><th>分配方式</th></tr></thead><tbody><tr><td>成员捐献</td><td>Zeny/材料</td><td>直接入公会仓库</td></tr><tr><td>GVG获胜奖励</td><td>Zeny + 公会经验</td><td>系统发放</td></tr><tr><td>领地税收</td><td>领地资源</td><td>领地主公会专属</td></tr><tr><td>赛季奖励</td><td>限定道具</td><td>全成员发放</td></tr></tbody></table><h2 id="公会外交" tabindex="-1">公会外交 <a class="header-anchor" href="#公会外交" aria-label="Permalink to &quot;公会外交&quot;">​</a></h2><p>RO3引入了公会外交系统：</p><ul><li><strong>结盟</strong>：与其他公会建立同盟关系</li><li><strong>宣战</strong>：向敌对公会宣战</li><li><strong>中立</strong>：保持中立状态</li><li><strong>领地协议</strong>：关于领土的互不侵犯条约</li></ul><h2 id="推荐公会结构" tabindex="-1">推荐公会结构 <a class="header-anchor" href="#推荐公会结构" aria-label="Permalink to &quot;推荐公会结构&quot;">​</a></h2><h3 id="_20人公会-小型" tabindex="-1">20人公会（小型） <a class="header-anchor" href="#_20人公会-小型" aria-label="Permalink to &quot;20人公会（小型）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>会长 x1</span></span>
<span class="line"><span>副会长 x1</span></span>
<span class="line"><span>精英 x3</span></span>
<span class="line"><span>成员 x15</span></span></code></pre></div><h3 id="_50人公会-中型" tabindex="-1">50人公会（中型） <a class="header-anchor" href="#_50人公会-中型" aria-label="Permalink to &quot;50人公会（中型）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>会长 x1</span></span>
<span class="line"><span>副会长 x2</span></span>
<span class="line"><span>精英 x5</span></span>
<span class="line"><span>成员 x42</span></span></code></pre></div><h3 id="_100人公会-大型" tabindex="-1">100人公会（大型） <a class="header-anchor" href="#_100人公会-大型" aria-label="Permalink to &quot;100人公会（大型）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>会长 x1</span></span>
<span class="line"><span>副会长 x3</span></span>
<span class="line"><span>编队长 x5（各带一队）</span></span>
<span class="line"><span>精英 x10</span></span>
<span class="line"><span>成员 x81</span></span></code></pre></div><h2 id="公会管理建议" tabindex="-1">公会管理建议 <a class="header-anchor" href="#公会管理建议" aria-label="Permalink to &quot;公会管理建议&quot;">​</a></h2><ol><li><strong>活跃管理</strong>：清理7天未上线的成员</li><li><strong>贡献制度</strong>：设置每周最低贡献要求</li><li><strong>GVG考勤</strong>：记录GVG参与度，作为奖励依据</li><li><strong>新人培养</strong>：安排老人带新人，稳定公会梯队</li><li><strong>外交维系</strong>：保持与同盟公会的沟通</li></ol><blockquote><p><strong>一句话</strong>：一个好的公会 = 活跃的管理 + 公平的制度 + 热闹的聊天频道。</p></blockquote>`,44)])])}const x=d(n,[["render",i]]);export{g as __pageData,x as default};
